CREATE OR REPLACE FUNCTION optimat.purge_stale_chat_trip_state()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'optimat', 'public'
AS $function$
DECLARE
    removed INTEGER;
BEGIN
    DELETE FROM optimat.chat_trip_state WHERE updated_at < NOW() - INTERVAL '30 days';
    GET DIAGNOSTICS removed = ROW_COUNT;
    RETURN removed;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
